import { Badge, EmptyState, PageHeader, StatCard } from "@/components/ui";
import { requireRole } from "@/lib/auth";
import { createClient } from "@/lib/supabase/server";
import { addGradingBand, createCommercialPlan, createGradingScheme, createOccurrence, inviteAdminAccess, inviteGuardianEnrollment, inviteTeacherAccess, manageCommercialPlan, registerMediaAsset, removeAdminContentItem, resendAccessInvitation, restoreTrashItem, setAdminContentStatus, updateAdminContentItem, updateCommercialPlan, updateMascot, updateOccurrenceStatus, updateSupportTicketStatus, updateUserProfileAdmin } from "@/app/admin/actions";
import { editTeamMessage, removeTeamMessage } from "@/app/message-actions";

const sections: Record<string, { title: string; description: string }> = {
  matriculas: { title: "Matrículas", description: "Solicitações de novas famílias e andamento do processo de entrada." },
  familias: { title: "Famílias", description: "Responsáveis cadastrados e seus vínculos autorizados." },
  usuarios: { title: "Usuários e acessos", description: "Convites, papéis e primeiro acesso controlados pela administração do Curió." },
  professores: { title: "Professores", description: "Equipe pedagógica, situação e dados profissionais." },
  vinculos: { title: "Vínculos", description: "Relações entre alunos, professores, famílias e turmas." },
  planos: { title: "Planos", description: "Planos disponíveis e assinaturas ativas na plataforma." },
  conteudo: { title: "Conteúdo", description: "Matérias, conteúdos e subconteúdos do catálogo pedagógico." },
  atividades: { title: "Missões e atividades", description: "Gestão central de Missões Cuca, Caderno Curió, materiais e avaliações." },
  personagens: { title: "Personagens", description: "Universo Curió, traços pedagógicos e ativos visuais." },
  gerador: { title: "Gerador", description: "Fila operacional das gerações assistidas por IA." },
  modelos: { title: "Modelos", description: "Modelos reutilizáveis para conteúdos e atividades." },
  series: { title: "Séries", description: "Anos escolares disponíveis para uso na plataforma." },
  mensagens: { title: "Mensagens", description: "Visão operacional dos canais de comunicação." },
  listas: { title: "Listas", description: "Listas salvas para organizar alunos e ações recorrentes." },
  documentos: { title: "Documentos", description: "Contratos, relatórios e documentos vinculados às famílias." },
  comunicacao: { title: "Comunicação", description: "Avisos e comunicados por público da plataforma." },
  lixeira: { title: "Lixeira", description: "Itens removidos com janela de restauração e auditoria." },
  configuracoes: { title: "Configurações", description: "Parâmetros gerais e controles de operação do Curió." },
  relatorios: { title: "Relatórios Acadêmicos", description: "Desempenho e progresso geral com base em estados pedagógicos agregados e relatórios gerados." },
  ocorrencias: { title: "Registro de Ocorrências", description: "Log interno de eventos, observações e comportamentos que precisam de acompanhamento." },
  materiais: { title: "Galeria de Materiais", description: "Repositório de materiais pedagógicos e recursos já cadastrados no Curió." },
  mascotes: { title: "Gestão de Mascotes", description: "Configuração dos personagens oficiais, avatares, poses e adesivos digitais." },
  auditoria: { title: "Auditoria de Sistema", description: "Monitoramento das alterações operacionais sem registrar conteúdo pessoal sensível." },
  calendario: { title: "Calendário Escolar", description: "Visão geral de encontros, eventos, provas e prazos cadastrados na agenda." },
  financeiro: { title: "Financeiro", description: "Mensalidades, pagamentos, assinaturas e situação financeira das famílias." },
  midia: { title: "Biblioteca de Mídia", description: "Gestão centralizada dos arquivos ativos reutilizados em conteúdos, materiais e mascotes." },
  acessos: { title: "Monitoramento de Acesso", description: "Histórico de entradas e saídas da plataforma para apoio operacional e segurança." },
  suporte: { title: "Suporte e Tickets", description: "Gestão de dúvidas, solicitações e acompanhamento de atendimento." },
  turmas: { title: "Registro de Turmas", description: "Composição das turmas, ano escolar, escola e vínculos ativos." },
  notas: { title: "Configuração de Notas", description: "Critérios e escalas de avaliação acadêmica, separados do mapa pedagógico." },
};

function dt(value?: string | null) {
  if (!value) return "—";
  return new Intl.DateTimeFormat("pt-BR", { dateStyle: "short", timeStyle: "short", timeZone: "America/Bahia" }).format(new Date(value));
}
function tone(status?: string | null): "green"|"yellow"|"pink"|"blue"|"neutral" {
  if (["active","paid","completed","approved","signed"].includes(status || "")) return "green";
  if (["new","pending","draft","processing","scheduled"].includes(status || "")) return "yellow";
  if (["failed","overdue","cancelled","rejected"].includes(status || "")) return "pink";
  return "blue";
}

export default async function AdminSectionPage({ params, searchParams }: { params: Promise<{ section: string }>; searchParams: Promise<{ erro?: string; sucesso?: string }> }) {
  const { section } = await params;
  const query = await searchParams;
  const copy = sections[section];
  if (!copy) notFound();
  await requireRole("admin");
  const supabase = await createClient();
  const header = <PageHeader eyebrow="Operação CURIÓ" title={copy.title} description={copy.description} />;
  const feedback = <>{query.erro && <div className="form-message form-error">{query.erro}</div>}{query.sucesso && <div className="form-message form-success">{query.sucesso}</div>}</>;

  if (section === "matriculas") {
    const [{ data: requests }, { data: grades }, { data: invitations }] = await Promise.all([
      supabase.from("enrollment_requests").select("id,guardian_name,email,phone_whatsapp,child_name,child_age,subjects,status,created_at,grades(name)").order("created_at", { ascending:false }).limit(80),
      supabase.from("grades").select("id,name,sort_order,active").eq("active",true).order("sort_order"),
      supabase.from("access_invitations").select("id,email,full_name,status,sent_at,accepted_at,last_error,student_id,created_at").eq("role","guardian").order("created_at",{ascending:false}).limit(60),
    ]);
    return <>{header}{feedback}<div className="access-setup-grid"><section className="panel access-create-card"><div className="panel-head"><div><span className="access-step">1</span><h2>Fazer matrícula e liberar a família</h2><p>O Admin cria o aluno, informa o e-mail do responsável e o Curió envia o link para definir a senha.</p></div></div><form action={inviteGuardianEnrollment} className="form-stack"><div className="form-row"><div className="field"><label>Nome do responsável *</label><input className="input" name="fullName" required/></div><div className="field"><label>Como prefere ser chamado</label><input className="input" name="preferredName"/></div></div><div className="form-row"><div className="field"><label>E-mail do responsável *</label><input className="input" type="email" name="email" required/></div><div className="field"><label>WhatsApp</label><input className="input" name="phone"/></div></div><div className="form-row"><div className="field"><label>Nome do aluno *</label><input className="input" name="childName" required/></div><div className="field"><label>Nome usado no portal</label><input className="input" name="childPreferredName"/></div></div><div className="form-row"><div className="field"><label>Ano escolar</label><select className="select" name="gradeId" defaultValue=""><option value="">Selecionar</option>{grades?.map((g:any)=><option key={g.id} value={g.id}>{g.name}</option>)}</select></div><div className="field"><label>Escola</label><input className="input" name="schoolName"/></div></div><div className="field"><label>Vínculo com a criança</label><input className="input" name="relationship" defaultValue="Responsável"/></div><button className="button button-primary button-block" type="submit">Criar matrícula e enviar primeiro acesso</button></form></section><section className="panel"><div className="panel-head"><div><span className="access-step access-step-pink">2</span><h2>Acessos enviados</h2><p>Ninguém cria conta sozinho. O convite nasce aqui.</p></div></div>{invitations?.length?<div className="form-stack">{invitations.map((invite:any)=><article className="access-invite-card" key={invite.id}><div className="flex space-between gap-8 wrap"><div><strong>{invite.full_name}</strong><p>{invite.email}</p></div><Badge tone={invite.status==="accepted"?"green":invite.status==="error"?"pink":"yellow"}>{invite.status==="accepted"?"Acesso ativo":invite.status==="error"?"Erro":"Convite enviado"}</Badge></div><small className="muted">{invite.accepted_at?`Senha definida em ${dt(invite.accepted_at)}`:invite.sent_at?`Enviado em ${dt(invite.sent_at)}`:"Aguardando envio"}</small>{invite.last_error&&<p className="form-message form-error">{invite.last_error}</p>}{invite.status!=="accepted"&&<form action={resendAccessInvitation}><input type="hidden" name="invitationId" value={invite.id}/><input type="hidden" name="returnTo" value="/admin/matriculas"/><button className="button button-secondary button-small" type="submit">Reenviar link</button></form>}</article>)}</div>:<EmptyState title="Nenhum acesso de família enviado" description="As matrículas criadas pelo Admin aparecerão aqui."/>}</section></div><section className="panel"><div className="panel-head"><div><h2>Interesses recebidos pelo site</h2><p>São apenas solicitações de contato; não criam conta automaticamente.</p></div></div>{requests?.length ? <div className="form-stack">{requests.map((item:any)=><article className="mission-card" key={item.id}><div className="flex space-between gap-8 wrap"><div><strong>{item.guardian_name}</strong><p>{item.child_name || "Criança não informada"} • {item.grades?.name || "Ano não informado"}</p></div><Badge tone={tone(item.status)}>{item.status}</Badge></div><small className="muted">{item.email} • {item.phone_whatsapp} • {dt(item.created_at)}</small></article>)}</div>:<EmptyState title="Nenhuma solicitação" description="Novos interesses enviados pelo site aparecerão aqui." />}</section></>;
  }
  if (section === "familias") {
    const { data } = await supabase.from("guardians").select("id,created_at,profiles(full_name,preferred_name,phone_whatsapp)").order("created_at",{ascending:false}).limit(80);
    return <>{header}<section className="panel">{data?.length?<div className="grid-3">{data.map((item:any)=><article className="mission-card" key={item.id}><h3>{item.profiles?.preferred_name || item.profiles?.full_name}</h3><p>{item.profiles?.phone_whatsapp || "Sem telefone"}</p><small className="muted">Desde {dt(item.created_at)}</small></article>)}</div>:<EmptyState title="Nenhuma família cadastrada" description="Responsáveis aparecerão aqui após cadastro e vínculo." />}</section></>;
  }
  if (section === "professores") {
    const [{ data }, { data: invitations }] = await Promise.all([
      supabase.from("teachers").select("id,active,created_at,phone_whatsapp,professional_description,profiles(full_name,preferred_name)").order("created_at",{ascending:false}).limit(80),
      supabase.from("access_invitations").select("id,email,full_name,status,sent_at,accepted_at,last_error,created_at").eq("role","teacher").order("created_at",{ascending:false}).limit(40),
    ]);
    return <>{header}{feedback}<div className="grid-2"><section className="panel"><div className="panel-head"><div><h2>Novo professor</h2><p>Cadastre a equipe e envie o link para a própria pessoa definir a senha.</p></div></div><form action={inviteTeacherAccess} className="form-stack"><div className="field"><label>Nome completo *</label><input className="input" name="fullName" required/></div><div className="field"><label>Nome preferido</label><input className="input" name="preferredName"/></div><div className="field"><label>E-mail *</label><input className="input" name="email" type="email" required/></div><div className="field"><label>WhatsApp</label><input className="input" name="phone"/></div><button className="button button-primary" type="submit">Cadastrar e enviar primeiro acesso</button></form></section><section className="panel"><div className="panel-head"><div><h2>Convites da equipe</h2><p>Acompanhe quem já definiu a senha.</p></div></div>{invitations?.length?<div className="form-stack">{invitations.map((invite:any)=><article className="access-invite-card" key={invite.id}><div className="flex space-between gap-8 wrap"><div><strong>{invite.full_name}</strong><p>{invite.email}</p></div><Badge tone={invite.status==="accepted"?"green":invite.status==="error"?"pink":"yellow"}>{invite.status}</Badge></div>{invite.status!=="accepted"&&<form action={resendAccessInvitation}><input type="hidden" name="invitationId" value={invite.id}/><input type="hidden" name="returnTo" value="/admin/professores"/><button className="button button-secondary button-small" type="submit">Reenviar acesso</button></form>}</article>)}</div>:<EmptyState title="Nenhum convite de professor" description="Os acessos enviados aparecerão aqui."/>}</section></div><section className="panel"><div className="panel-head"><div><h2>Equipe cadastrada</h2></div></div>{data?.length?<div className="grid-3">{data.map((item:any)=><article className="mission-card" key={item.id}><div className="flex space-between gap-8 wrap"><h3>{item.profiles?.preferred_name || item.profiles?.full_name}</h3><Badge tone={item.active?"green":"neutral"}>{item.active?"Ativo":"Inativo"}</Badge></div><p>{item.professional_description || "Descrição profissional não preenchida"}</p><small className="muted">{item.phone_whatsapp || "Sem telefone"}</small></article>)}</div>:<EmptyState title="Nenhum professor cadastrado" description="A equipe pedagógica aparecerá aqui." />}</section></>;
  }
  if (section === "usuarios") {
    const [{ data: invitations }, { data: profiles }, { data: roleRows }] = await Promise.all([
      supabase.from("access_invitations").select("id,email,role,full_name,status,sent_at,accepted_at,last_error,created_at").order("created_at",{ascending:false}).limit(120),
      supabase.from("profiles").select("id,full_name,preferred_name,phone_whatsapp,created_at").order("created_at",{ascending:false}).limit(120),
      supabase.from("user_roles").select("user_id,role"),
    ]);
    const rolesByUser = new Map<string,string[]>();
    for (const row of roleRows ?? []) rolesByUser.set(row.user_id,[...(rolesByUser.get(row.user_id)||[]),row.role]);
    return <>{header}{feedback}<div className="grid-2"><section className="panel"><div className="panel-head"><div><h2>Convidar outro administrador</h2><p>Admins podem operar e editar todas as áreas permitidas pelo sistema.</p></div></div><form action={inviteAdminAccess} className="form-stack"><div className="field"><label>Nome completo *</label><input className="input" name="fullName" required/></div><div className="field"><label>Nome preferido</label><input className="input" name="preferredName"/></div><div className="field"><label>E-mail *</label><input className="input" type="email" name="email" required/></div><div className="field"><label>WhatsApp</label><input className="input" name="phone"/></div><button className="button button-primary" type="submit">Enviar acesso de Admin</button></form></section><section className="panel"><div className="notice">Não existe “criar conta” público. Família, professor e novos administradores entram somente depois de uma liberação do Admin.</div><div className="access-flow-mini"><span><b>1</b>Admin cadastra</span><i>→</i><span><b>2</b>E-mail é enviado</span><i>→</i><span><b>3</b>Usuário define senha</span><i>→</i><span><b>4</b>Portal correto abre</span></div></section></div><section className="panel"><div className="panel-head"><div><h2>Convites e primeiro acesso</h2><p>Histórico institucional de liberação de contas.</p></div></div>{invitations?.length?<table className="data-table"><thead><tr><th>Usuário</th><th>Papel</th><th>Status</th><th>Envio</th><th>Ação</th></tr></thead><tbody>{invitations.map((invite:any)=><tr key={invite.id}><td><strong>{invite.full_name}</strong><br/><small>{invite.email}</small></td><td><Badge tone={invite.role==="admin"?"pink":invite.role==="teacher"?"blue":"green"}>{invite.role==="admin"?"Admin":invite.role==="teacher"?"Professor":"Família"}</Badge></td><td>{invite.status==="accepted"?"Acesso ativo":invite.status}</td><td>{dt(invite.accepted_at||invite.sent_at||invite.created_at)}</td><td>{invite.status!=="accepted"&&<form action={resendAccessInvitation}><input type="hidden" name="invitationId" value={invite.id}/><input type="hidden" name="returnTo" value="/admin/usuarios"/><button className="button button-secondary button-small" type="submit">Reenviar</button></form>}</td></tr>)}</tbody></table>:<EmptyState title="Nenhum convite registrado" description="Os próximos acessos institucionais aparecerão aqui."/>}</section><section className="panel"><div className="panel-head"><div><h2>Perfis existentes</h2><p>O mesmo usuário pode ter mais de um papel, como Admin + Professor.</p></div></div>{profiles?.length?<div className="grid-3">{profiles.map((profile:any)=><article className="mission-card" key={profile.id}><h3>{profile.preferred_name||profile.full_name}</h3><p>{profile.full_name}</p><div className="flex gap-8 wrap">{(rolesByUser.get(profile.id)||[]).map((role)=><Badge key={role} tone={role==="admin"?"pink":role==="teacher"?"blue":role==="guardian"?"green":"yellow"}>{role}</Badge>)}</div><small className="muted">{profile.phone_whatsapp||"Sem telefone"}</small><details className="mascot-settings"><summary>Editar perfil</summary><form action={updateUserProfileAdmin} className="form-stack"><input type="hidden" name="profileId" value={profile.id}/><div className="field"><label>Nome completo</label><input className="input" name="fullName" defaultValue={profile.full_name} required/></div><div className="field"><label>Nome preferido</label><input className="input" name="preferredName" defaultValue={profile.preferred_name||""}/></div><div className="field"><label>WhatsApp</label><input className="input" name="phone" defaultValue={profile.phone_whatsapp||""}/></div><button className="button button-secondary button-small" type="submit">Salvar alterações</button></form></details></article>)}</div>:<EmptyState title="Nenhum perfil" description="Perfis autenticados aparecerão aqui."/>}</section></>;
  }
  if (section === "vinculos") {
    const [{count:teacherLinks},{count:guardianLinks},{count:classLinks}] = await Promise.all([
      supabase.from("teacher_students").select("student_id",{count:"exact",head:true}).eq("active",true),
      supabase.from("guardian_students").select("student_id",{count:"exact",head:true}),
      supabase.from("class_students").select("student_id",{count:"exact",head:true}).eq("active",true),
    ]);
    return <>{header}<div className="stats-grid"><StatCard value={teacherLinks??0} label="Professor ↔ aluno"/><StatCard value={guardianLinks??0} label="Família ↔ aluno"/><StatCard value={classLinks??0} label="Turma ↔ aluno"/><StatCard value="RLS" label="Acesso protegido"/></div><section className="panel"><p className="muted">Os vínculos controlam o que cada perfil consegue visualizar. Grupos pedagógicos não alteram matrícula nem vínculo oficial.</p></section></>;
  }
  if (section === "planos") {
    const [{ data: plans }, { count: subs }] = await Promise.all([
      supabase.from("plans").select("id,name,description,monthly_price,currency,features,active,billing_interval,meetings_per_month,delivery_mode,visible_on_landing,available_for_enrollment,badge,sort_order,archived_at,deleted_at").is("deleted_at", null).order("sort_order").order("created_at"),
      supabase.from("subscriptions").select("id", { count: "exact", head: true }).eq("status", "active"),
    ]);
    const activeCount = (plans ?? []).filter((p: any) => p.active && !p.archived_at).length;
    const landingCount = (plans ?? []).filter((p: any) => p.visible_on_landing && p.active && !p.archived_at).length;
    return <>{header}{feedback}
      <div className="stats-grid">
        <StatCard value={plans?.length ?? 0} label="Planos cadastrados"/>
        <StatCard value={activeCount} label="Planos ativos"/>
        <StatCard value={landingCount} label="Visíveis na landing"/>
        <StatCard value={subs ?? 0} label="Assinaturas ativas"/>
      </div>
      <section className="panel plan-create-panel">
        <div className="panel-head"><div><h2>Novo plano</h2><p>Crie, edite, arquive ou retire da landing sem apagar o histórico financeiro.</p></div></div>
        <details className="plan-editor"><summary className="button button-primary button-small">+ Criar novo plano</summary>
          <form action={createCommercialPlan} className="form-stack plan-form">
            <div className="form-row"><div className="field"><label>Nome *</label><input className="input" name="name" required/></div><div className="field"><label>Preço mensal *</label><input className="input" name="monthlyPrice" type="number" min="0" step="0.01" required/></div></div>
            <div className="field"><label>Descrição *</label><textarea className="textarea" name="description" required/></div>
            <div className="form-row"><div className="field"><label>Encontros/mês</label><input className="input" name="meetingsPerMonth" type="number" min="0" defaultValue="4"/></div><div className="field"><label>Modalidade</label><select className="select" name="deliveryMode" defaultValue="online"><option value="online">Online</option><option value="hybrid">Híbrido</option><option value="presential">Presencial</option></select></div></div>
            <div className="form-row"><div className="field"><label>Selo</label><input className="input" name="badge" placeholder="Piloto, Recomendado..."/></div><div className="field"><label>Ordem</label><input className="input" name="sortOrder" type="number" defaultValue="60"/></div></div>
            <div className="field"><label>Benefícios</label><textarea className="textarea" name="features" placeholder="Um por linha"/></div>
            <div className="plan-check-row"><label><input type="checkbox" name="active"/> Ativo</label><label><input type="checkbox" name="visibleOnLanding"/> Visível na landing</label><label><input type="checkbox" name="availableForEnrollment" defaultChecked/> Disponível para matrícula</label></div>
            <button className="button button-primary" type="submit">Criar plano</button>
          </form>
        </details>
      </section>
      <section className="panel">
        <div className="plan-management-grid">{plans?.map((p: any) => {
          const lifecycle = p.archived_at ? "Arquivado" : p.active ? "Ativo" : "Rascunho";
          const statusTone = p.archived_at ? "neutral" : p.active ? "green" : "yellow";
          return <article className={`plan-admin-card ${p.badge === "Recomendado" ? "plan-featured" : ""}`} key={p.id}>
            <div className="flex gap-8 wrap"><Badge tone={statusTone}>{lifecycle}</Badge>{p.badge && <Badge tone={p.badge === "Piloto" ? "pink" : "blue"}>{p.badge}</Badge>}</div>
            <h3>{p.name}</h3><p>{p.description}</p>
            <div className="plan-price-line"><strong>R$ {Number(p.monthly_price || 0).toFixed(2).replace(".", ",")}</strong><span>/ Mensal</span></div>
            <div className="plan-meta-chips"><span>{p.meetings_per_month} encontros</span><span>{p.delivery_mode === "online" ? "Online" : p.delivery_mode}</span>{p.visible_on_landing && <span>Visível na landing</span>}{p.available_for_enrollment && <span>Disponível para matrícula</span>}</div>
            <details className="plan-editor"><summary>Editar plano</summary><form action={updateCommercialPlan} className="form-stack plan-form">
              <input type="hidden" name="planId" value={p.id}/><div className="field"><label>Nome</label><input className="input" name="name" defaultValue={p.name} required/></div><div className="field"><label>Descrição</label><textarea className="textarea" name="description" defaultValue={p.description || ""} required/></div>
              <div className="form-row"><div className="field"><label>Preço mensal</label><input className="input" name="monthlyPrice" type="number" step="0.01" defaultValue={Number(p.monthly_price || 0)} required/></div><div className="field"><label>Encontros/mês</label><input className="input" name="meetingsPerMonth" type="number" defaultValue={p.meetings_per_month || 0}/></div></div>
              <div className="form-row"><div className="field"><label>Modalidade</label><select className="select" name="deliveryMode" defaultValue={p.delivery_mode || "online"}><option value="online">Online</option><option value="hybrid">Híbrido</option><option value="presential">Presencial</option></select></div><div className="field"><label>Selo</label><input className="input" name="badge" defaultValue={p.badge || ""}/></div></div>
              <div className="field"><label>Benefícios</label><textarea className="textarea" name="features" defaultValue={(p.features || []).join("\n")}/></div><input type="hidden" name="sortOrder" value={p.sort_order || 0}/>
              <div className="plan-check-row"><label><input type="checkbox" name="active" defaultChecked={p.active}/> Ativo</label><label><input type="checkbox" name="visibleOnLanding" defaultChecked={p.visible_on_landing}/> Visível na landing</label><label><input type="checkbox" name="availableForEnrollment" defaultChecked={p.available_for_enrollment}/> Matrícula</label></div>
              <button className="button button-secondary button-small" type="submit">Salvar alterações</button>
            </form></details>
            <div className="plan-admin-actions">
              <form action={manageCommercialPlan}><input type="hidden" name="planId" value={p.id}/><input type="hidden" name="action" value={p.active && !p.archived_at ? "draft" : "activate"}/><button className="button button-secondary button-small" type="submit">{p.active && !p.archived_at ? "Virar rascunho" : "Ativar"}</button></form>
              {!p.archived_at && <form action={manageCommercialPlan}><input type="hidden" name="planId" value={p.id}/><input type="hidden" name="action" value="archive"/><button className="button button-ghost button-small" type="submit">Arquivar</button></form>}
              <form action={manageCommercialPlan}><input type="hidden" name="planId" value={p.id}/><input type="hidden" name="action" value="delete"/><button className="button button-danger button-small" type="submit">Excluir</button></form>
            </div>
          </article>;
        })}</div>
        {!plans?.length && <EmptyState title="Nenhum plano cadastrado" description="Crie o primeiro plano comercial do Curió."/>}
      </section>
    </>;
  }
  if (section === "atividades") {
    const [{ data: missions }, { data: materials }, { data: notebooks }, { data: assessments }] = await Promise.all([
      supabase.from("missions").select("id,title,objective,status,updated_at,teachers(profiles(full_name,preferred_name))").order("updated_at", { ascending: false }).limit(40),
      supabase.from("materials").select("id,title,description,status,material_type,updated_at,teachers(profiles(full_name,preferred_name))").order("updated_at", { ascending: false }).limit(40),
      supabase.from("notebook_activities").select("id,title,description,status,updated_at,teachers(profiles(full_name,preferred_name))").order("updated_at", { ascending: false }).limit(40),
      supabase.from("assessments").select("id,title,instructions,status,updated_at,teachers(profiles(full_name,preferred_name))").order("updated_at", { ascending: false }).limit(40),
    ]);
    const groups = [
      { kind: "mission", title: "Missões Cuca", items: missions ?? [] },
      { kind: "notebook", title: "Caderno Curió", items: notebooks ?? [] },
      { kind: "material", title: "Materiais", items: materials ?? [] },
      { kind: "assessment", title: "Avaliações", items: assessments ?? [] },
    ] as const;
    return <>{header}{feedback}<div className="notice">Rascunhos sem vínculo podem ser excluídos. Itens já publicados, atribuídos ou com histórico são arquivados para não apagar evidências.</div>{groups.map((group) => <section className="panel" key={group.kind}><div className="panel-head"><div><h2>{group.title}</h2><p>{group.items.length} item(ns) recente(s)</p></div></div>{group.items.length ? <div className="grid-3">{group.items.map((item: any) => {const description = group.kind === "mission" ? item.objective : group.kind === "assessment" ? item.instructions : item.description; return <article className="mission-card" key={`${group.kind}-${item.id}`}><div className="flex space-between gap-8 wrap"><Badge tone={tone(item.status)}>{item.status}</Badge><small className="muted">{item.teachers?.profiles?.preferred_name || item.teachers?.profiles?.full_name || "Equipe Curió"}</small></div><h3>{item.title}</h3><p>{description || "Sem descrição"}</p><details className="plan-editor"><summary>Editar</summary><form action={updateAdminContentItem} className="form-stack plan-form"><input type="hidden" name="kind" value={group.kind}/><input type="hidden" name="id" value={item.id}/><div className="field"><label>Título</label><input className="input" name="title" defaultValue={item.title} required/></div><div className="field"><label>{group.kind === "mission" ? "Objetivo" : group.kind === "assessment" ? "Instruções" : "Descrição"}</label><textarea className="textarea" name="description" defaultValue={description || ""}/></div><button className="button button-secondary button-small" type="submit">Salvar</button></form></details><div className="plan-admin-actions">{item.status !== "archived" ? <form action={setAdminContentStatus}><input type="hidden" name="kind" value={group.kind}/><input type="hidden" name="id" value={item.id}/><input type="hidden" name="status" value="archived"/><button className="button button-ghost button-small" type="submit">Arquivar</button></form> : <form action={setAdminContentStatus}><input type="hidden" name="kind" value={group.kind}/><input type="hidden" name="id" value={item.id}/><input type="hidden" name="status" value="draft"/><button className="button button-secondary button-small" type="submit">Voltar a rascunho</button></form>}<form action={removeAdminContentItem}><input type="hidden" name="kind" value={group.kind}/><input type="hidden" name="id" value={item.id}/><button className="button button-danger button-small" type="submit">Excluir</button></form></div></article>})}</div> : <EmptyState title={`Nenhum item em ${group.title}`} description="Quando houver itens, eles aparecerão aqui."/>}</section>)}</>;
  }

  if (section === "conteudo") {
    const [{data:subjects},{data:contents},{count:skills}] = await Promise.all([supabase.from("subjects").select("id,name,active").order("name"),supabase.from("contents").select("id,name,parent_id,subjects(name)").order("name").limit(120),supabase.from("skills").select("id",{count:"exact",head:true}).eq("active",true)]);
    return <>{header}<div className="stats-grid"><StatCard value={subjects?.length??0} label="Matérias"/><StatCard value={contents?.length??0} label="Conteúdos"/><StatCard value={skills??0} label="Habilidades"/><StatCard value="≠" label="Conteúdo ≠ habilidade"/></div><section className="panel">{contents?.length?<div className="grid-3">{contents.slice(0,36).map((c:any)=><article className="mission-card" key={c.id}><Badge tone="blue">{c.subjects?.name||"Matéria"}</Badge><h3>{c.name}</h3><small className="muted">{c.parent_id?"Subconteúdo":"Conteúdo"}</small></article>)}</div>:<EmptyState title="Catálogo vazio" description="Conteúdos pedagógicos aparecerão aqui."/>}</section></>;
  }
  if (section === "personagens" || section === "mascotes") {
    const {data} = await supabase.from("characters").select("id,slug,name,species,pedagogical_trait,description,assets,active,sort_order").order("sort_order");
    return <>{header}<section className="panel">{data?.length?<div className="mascot-admin-grid">{data.map((c:any)=>{const image=c.assets?.principal||c.assets?.avatar||c.assets?.sticker; return <article className="mascot-admin-card" key={c.id}>{image?<div className="mascot-admin-visual"><img src={image} alt={c.name}/></div>:null}<div className="flex space-between gap-8 wrap"><Badge tone={c.active?"green":"neutral"}>{c.active?"Ativo":"Inativo"}</Badge><small className="muted">#{c.sort_order}</small></div><h3>{c.name}</h3><p><strong>{c.pedagogical_trait}</strong><br/>{c.description||c.species}</p><div className="asset-chips">{Object.keys(c.assets||{}).map((key)=><span key={key}>{key}</span>)}</div><details className="mascot-settings"><summary>Configurar mascote</summary><form action={updateMascot} className="form-stack"><input type="hidden" name="characterId" value={c.id}/><label className="checkbox-line"><input type="checkbox" name="active" defaultChecked={c.active}/> Mascote ativo</label><div className="field"><label>Traço pedagógico</label><input className="input" name="trait" defaultValue={c.pedagogical_trait} required/></div><div className="field"><label>Descrição</label><textarea className="textarea" name="description" defaultValue={c.description||""}/></div><div className="field"><label>Imagem principal</label><input className="input" name="principal" defaultValue={c.assets?.principal||""}/></div><div className="field"><label>Avatar</label><input className="input" name="avatar" defaultValue={c.assets?.avatar||""}/></div><div className="field"><label>Adesivo</label><input className="input" name="sticker" defaultValue={c.assets?.sticker||""}/></div><div className="field"><label>Pose de atividade</label><input className="input" name="activity" defaultValue={c.assets?.activity||""}/></div><div className="field"><label>Pose pensando</label><input className="input" name="thinking" defaultValue={c.assets?.thinking||""}/></div><button className="button button-secondary button-small" type="submit">Salvar configuração</button></form></details></article>})}</div>:<EmptyState title="Nenhum mascote cadastrado" description="Os personagens oficiais do Curió aparecerão aqui."/>}</section></>;
  }
  if (section === "gerador") {
    const {data} = await supabase.from("generation_jobs").select("id,job_type,status,result_entity_type,error_message,created_at,started_at,finished_at").order("created_at",{ascending:false}).limit(80);
    return <>{header}<section className="panel">{data?.length?<div className="form-stack">{data.map((j:any)=><article className="mission-card" key={j.id}><div className="flex space-between gap-8 wrap"><strong>{j.job_type}</strong><Badge tone={tone(j.status)}>{j.status}</Badge></div><small className="muted">{dt(j.created_at)}{j.result_entity_type?` • ${j.result_entity_type}`:""}</small>{j.error_message&&<p>{j.error_message}</p>}</article>)}</div>:<EmptyState title="Nenhuma geração registrada" description="A fila do gerador aparecerá aqui."/>}</section></>;
  }
  if (section === "modelos") {
    const {data}=await supabase.from("content_templates").select("id,name,template_type,description,shared,active,created_at").order("created_at",{ascending:false}).limit(80);
    return <>{header}<section className="panel">{data?.length?<div className="grid-3">{data.map((t:any)=><article className="mission-card" key={t.id}><div className="flex gap-8 wrap"><Badge tone="blue">{t.template_type}</Badge>{t.shared&&<Badge tone="green">Compartilhado</Badge>}</div><h3>{t.name}</h3><p>{t.description||"Modelo Curió"}</p></article>)}</div>:<EmptyState title="Nenhum modelo cadastrado" description="Modelos reutilizáveis aparecerão aqui."/>}</section></>;
  }
  if (section === "series") {
    const {data}=await supabase.from("grades").select("id,name,sort_order,active").order("sort_order");
    return <>{header}<section className="panel"><div className="grid-3">{data?.map((g:any)=><article className="mission-card" key={g.id}><Badge tone={g.active?"green":"neutral"}>{g.active?"Ativo":"Inativo"}</Badge><h3>{g.name}</h3><p>Ordem pedagógica {g.sort_order}</p></article>)}</div></section></>;
  }
  if (section === "mensagens") {
    const [{ count: threads }, { count: messages }, { data: recent }] = await Promise.all([
      supabase.from("message_threads").select("id", { count: "exact", head: true }),
      supabase.from("messages").select("id", { count: "exact", head: true }).is("deleted_at", null),
      supabase.from("messages").select("id,thread_id,sender_user_id,body,created_at,edited_at,deleted_at,message_threads(subject)").is("deleted_at", null).order("created_at", { ascending: false }).limit(40),
    ]);
    const senderIds = [...new Set((recent ?? []).map((m: any) => m.sender_user_id))];
    const { data: senderProfiles } = senderIds.length ? await supabase.from("profiles").select("id,full_name,preferred_name").in("id", senderIds) : { data: [] as any[] };
    const senderName = new Map((senderProfiles ?? []).map((profile: any) => [profile.id, profile.preferred_name || profile.full_name]));
    return <>{header}{feedback}<div className="stats-grid"><StatCard value={threads??0} label="Conversas"/><StatCard value={messages??0} label="Mensagens ativas"/><StatCard value="Editar" label="Moderação disponível"/><StatCard value="RLS" label="Participantes protegidos"/></div><section className="panel"><div className="panel-head"><div><h2>Mensagens recentes</h2><p>O Admin pode corrigir ou remover mensagens operacionais. Remover não apaga silenciosamente o histórico.</p></div></div>{recent?.length?<div className="form-stack">{recent.map((m:any)=><article className="mission-card" key={m.id}><div className="flex space-between gap-8 wrap"><div><strong>{m.message_threads?.subject||"Conversa"}</strong><p>{senderName.get(m.sender_user_id) || "Usuário"}</p></div><small className="muted">{dt(m.created_at)}{m.edited_at?" • editada":""}</small></div><p>{m.body}</p><details className="plan-editor"><summary>Editar mensagem</summary><form action={editTeamMessage} className="form-stack plan-form"><input type="hidden" name="messageId" value={m.id}/><input type="hidden" name="returnPath" value="/admin/mensagens"/><textarea className="textarea" name="body" defaultValue={m.body} required/><button className="button button-secondary button-small" type="submit">Salvar edição</button></form></details><form action={removeTeamMessage}><input type="hidden" name="messageId" value={m.id}/><input type="hidden" name="returnPath" value="/admin/mensagens"/><button className="button button-danger button-small" type="submit">Remover mensagem</button></form></article>)}</div>:<EmptyState title="Nenhuma mensagem" description="Mensagens enviadas aparecerão aqui."/>}</section></>;
  }
  if (section === "listas") {
    const {data}=await supabase.from("saved_lists").select("id,name,description,created_at").order("created_at",{ascending:false}).limit(80);
    return <>{header}<section className="panel">{data?.length?<div className="grid-3">{data.map((l:any)=><article className="mission-card" key={l.id}><h3>{l.name}</h3><p>{l.description||"Lista salva"}</p><small className="muted">{dt(l.created_at)}</small></article>)}</div>:<EmptyState title="Nenhuma lista salva" description="Listas de operação aparecerão aqui."/>}</section></>;
  }
  if (section === "documentos") {
    const {data}=await supabase.from("documents").select("id,title,document_type,student_id,guardian_id,visible_to_guardian,created_at").order("created_at",{ascending:false}).limit(80);
    return <>{header}<section className="panel">{data?.length?<div className="form-stack">{data.map((d:any)=><article className="mission-card" key={d.id}><div className="flex space-between gap-8 wrap"><strong>{d.title}</strong><Badge tone={d.visible_to_guardian?"green":"neutral"}>{d.document_type}</Badge></div><small className="muted">{dt(d.created_at)}</small></article>)}</div>:<EmptyState title="Nenhum documento cadastrado" description="Documentos operacionais aparecerão aqui."/>}</section></>;
  }
  if (section === "comunicacao") {
    const {data}=await supabase.from("announcements").select("id,title,body,audience,active,starts_at,ends_at,created_at").order("created_at",{ascending:false}).limit(80);
    return <>{header}<section className="panel">{data?.length?<div className="form-stack">{data.map((a:any)=><article className="mission-card" key={a.id}><div className="flex space-between gap-8 wrap"><strong>{a.title}</strong><Badge tone={a.active?"green":"neutral"}>{a.audience}</Badge></div><p>{a.body}</p><small className="muted">{dt(a.starts_at||a.created_at)}</small></article>)}</div>:<EmptyState title="Nenhum comunicado" description="Comunicados publicados aparecerão aqui."/>}</section></>;
  }

  if (section === "relatorios") {
    const [{data:reports},{count:students},{count:states},{count:review}] = await Promise.all([
      supabase.from("generated_reports").select("id,student_id,report_type,period_start,period_end,narrative,file_path,created_at,students(preferred_name,full_name)").order("created_at",{ascending:false}).limit(40),
      supabase.from("students").select("id",{count:"exact",head:true}).eq("status","active"),
      supabase.from("student_skill_states").select("student_id",{count:"exact",head:true}),
      supabase.from("student_skill_states").select("student_id",{count:"exact",head:true}).eq("needs_teacher_review",true),
    ]);
    return <>{header}<div className="stats-grid"><StatCard value={students??0} label="Alunos ativos"/><StatCard value={states??0} label="Estados de habilidade"/><StatCard value={review??0} label="Pontos para revisão"/><StatCard value={reports?.length??0} label="Relatórios recentes"/></div><section className="panel"><div className="notice">O relatório acadêmico usa estados agregados. Evidência bruta continua restrita à equipe pedagógica.</div>{reports?.length?<div className="form-stack">{reports.map((r:any)=><article className="mission-card" key={r.id}><div className="flex space-between gap-8 wrap"><div><strong>{r.students?.preferred_name||r.students?.full_name||"Aluno"}</strong><p>{r.report_type}</p></div><Badge tone="blue">{r.period_start||"Período"} → {r.period_end||"atual"}</Badge></div>{r.narrative&&<p className="muted">{r.narrative.slice(0,220)}{r.narrative.length>220?"…":""}</p>}<small className="muted">Gerado em {dt(r.created_at)}</small></article>)}</div>:<EmptyState title="Nenhum relatório gerado" description="Os relatórios acadêmicos aparecerão aqui quando forem produzidos."/>}</section></>;
  }
  if (section === "ocorrencias") {
    const [{data:items},{data:students}] = await Promise.all([
      supabase.from("student_occurrences").select("id,title,description,occurrence_type,severity,status,occurred_at,students(preferred_name,full_name)").order("occurred_at",{ascending:false}).limit(80),
      supabase.from("students").select("id,preferred_name,full_name").eq("status","active").order("preferred_name").limit(200),
    ]);
    return <>{header}<div className="grid-2"><section className="panel"><div className="panel-head"><div><h2>Registrar ocorrência</h2><p>Uso interno da equipe. Não aparece automaticamente para criança ou família.</p></div></div><form action={createOccurrence} className="form-stack"><div className="field"><label>Aluno</label><select className="select" name="studentId" required><option value="">Selecione</option>{students?.map((st:any)=><option value={st.id} key={st.id}>{st.preferred_name||st.full_name}</option>)}</select></div><div className="form-row"><div className="field"><label>Tipo</label><select className="select" name="type" defaultValue="observation"><option value="observation">Observação</option><option value="positive">Positiva</option><option value="attention">Atenção</option><option value="behavior">Comportamento</option><option value="attendance">Frequência</option><option value="other">Outro</option></select></div><div className="field"><label>Nível</label><select className="select" name="severity" defaultValue="1"><option value="1">1 · Leve</option><option value="2">2 · Acompanhar</option><option value="3">3 · Prioritário</option></select></div></div><div className="field"><label>Título</label><input className="input" name="title" required maxLength={120}/></div><div className="field"><label>Descrição</label><textarea className="textarea" name="description" required/></div><button className="button button-primary" type="submit">Registrar ocorrência</button></form></section><section className="panel"><div className="panel-head"><div><h2>Últimos registros</h2><p>Histórico operacional em ordem cronológica.</p></div></div>{items?.length?<div className="form-stack">{items.map((i:any)=><article className={`occurrence-card severity-${i.severity}`} key={i.id}><div className="flex space-between gap-8 wrap"><strong>{i.students?.preferred_name||i.students?.full_name||"Aluno"}</strong><Badge tone={i.status==="resolved"?"green":i.severity===3?"pink":"yellow"}>{i.status}</Badge></div><h3>{i.title}</h3><p>{i.description}</p><small className="muted">{i.occurrence_type} • {dt(i.occurred_at)}</small><form action={updateOccurrenceStatus} className="ticket-actions"><input type="hidden" name="occurrenceId" value={i.id}/><select className="select" name="status" defaultValue={i.status}><option value="open">Aberta</option><option value="monitoring">Em acompanhamento</option><option value="resolved">Resolvida</option></select><button className="button button-secondary button-small" type="submit">Atualizar</button></form></article>)}</div>:<EmptyState title="Sem ocorrências" description="Nenhum registro foi criado ainda."/>}</section></div></>;
  }
  if (section === "materiais") {
    const {data}=await supabase.from("materials").select("id,title,description,material_type,file_path,external_url,status,created_at,subjects(name),grades(name)").order("created_at",{ascending:false}).limit(100);
    return <>{header}<section className="panel">{data?.length?<div className="grid-3">{data.map((m:any)=><article className="resource-card" key={m.id}><div className="resource-card-icon">📚</div><div className="flex gap-8 wrap"><Badge tone={tone(m.status)}>{m.status}</Badge><Badge tone="blue">{m.material_type}</Badge></div><h3>{m.title}</h3><p>{m.description||"Material pedagógico"}</p><small className="muted">{m.subjects?.name||"Geral"}{m.grades?.name?` • ${m.grades.name}`:""}</small>{(m.file_path||m.external_url)&&<div className="asset-path">{m.file_path||m.external_url}</div>}</article>)}</div>:<EmptyState title="Galeria vazia" description="Os materiais criados pela equipe aparecerão aqui."/>}</section></>;
  }
  if (section === "auditoria") {
    const {data}=await supabase.from("system_audit_logs").select("id,actor_user_id,action,entity_type,entity_id,changed_columns,created_at,profiles(full_name,preferred_name)").order("created_at",{ascending:false}).limit(120);
    return <>{header}<section className="panel"><div className="notice">A auditoria registra ação, entidade, ID e nomes das colunas alteradas — não copia o conteúdo pessoal das linhas.</div>{data?.length?<div className="audit-list">{data.map((a:any)=><article className="audit-row" key={a.id}><span className={`audit-action audit-${a.action}`}>{a.action}</span><div><strong>{a.entity_type}</strong><p>{a.profiles?.preferred_name||a.profiles?.full_name||"Sistema"} • {dt(a.created_at)}</p>{a.changed_columns?.length?<small className="muted">Campos: {a.changed_columns.join(", ")}</small>:null}</div><code>{a.entity_id||"—"}</code></article>)}</div>:<EmptyState title="Sem eventos de auditoria" description="As próximas alterações relevantes aparecerão aqui."/>}</section></>;
  }
  if (section === "calendario") {
    const {data}=await supabase.from("agenda_events").select("id,title,description,event_type,starts_at,ends_at,status,location,meeting_url,visible_to_student,visible_to_guardian,classes(name)").order("starts_at",{ascending:true}).limit(100);
    return <>{header}<section className="panel">{data?.length?<div className="calendar-admin-list">{data.map((e:any)=><article className="calendar-admin-item" key={e.id}><div className="calendar-date"><strong>{new Intl.DateTimeFormat("pt-BR",{day:"2-digit",timeZone:"America/Bahia"}).format(new Date(e.starts_at))}</strong><span>{new Intl.DateTimeFormat("pt-BR",{month:"short",timeZone:"America/Bahia"}).format(new Date(e.starts_at))}</span></div><div><div className="flex gap-8 wrap"><Badge tone={tone(e.status)}>{e.status}</Badge><Badge tone="blue">{e.event_type}</Badge></div><h3>{e.title}</h3><p>{e.description||e.classes?.name||e.location||"Evento Curió"}</p><small className="muted">{dt(e.starts_at)}{e.ends_at?` → ${dt(e.ends_at)}`:""}</small></div></article>)}</div>:<EmptyState title="Calendário vazio" description="Eventos criados pela equipe aparecerão aqui."/>}</section></>;
  }
  if (section === "financeiro") {
    const [{data:payments},{count:activeSubs},{count:overdue}] = await Promise.all([
      supabase.from("payments").select("id,amount,currency,due_date,paid_at,status,provider,subscriptions(student_id,students(preferred_name,full_name),plans(name))").order("due_date",{ascending:false}).limit(100),
      supabase.from("subscriptions").select("id",{count:"exact",head:true}).eq("status","active"),
      supabase.from("payments").select("id",{count:"exact",head:true}).eq("status","overdue"),
    ]);
    const received=(payments||[]).filter((p:any)=>p.status==="paid").reduce((sum:number,p:any)=>sum+Number(p.amount||0),0);
    return <>{header}<div className="stats-grid"><StatCard value={activeSubs??0} label="Assinaturas ativas"/><StatCard value={overdue??0} label="Pagamentos vencidos"/><StatCard value={`R$ ${received.toFixed(2).replace(".",",")}`} label="Recebido no histórico exibido"/><StatCard value={payments?.length??0} label="Lançamentos recentes"/></div><section className="panel">{payments?.length?<table className="data-table"><thead><tr><th>Aluno</th><th>Plano</th><th>Valor</th><th>Vencimento</th><th>Status</th></tr></thead><tbody>{payments.map((p:any)=><tr key={p.id}><td>{p.subscriptions?.students?.preferred_name||p.subscriptions?.students?.full_name||"—"}</td><td>{p.subscriptions?.plans?.name||"—"}</td><td>R$ {Number(p.amount||0).toFixed(2).replace(".",",")}</td><td>{p.due_date||"—"}</td><td><Badge tone={tone(p.status)}>{p.status}</Badge></td></tr>)}</tbody></table>:<EmptyState title="Sem lançamentos financeiros" description="Pagamentos e mensalidades aparecerão aqui."/>}</section></>;
  }
  if (section === "midia") {
    const {data}=await supabase.from("media_assets").select("id,name,category,file_path,external_url,mime_type,alt_text,active,source_entity_type,created_at").order("created_at",{ascending:false}).limit(120);
    return <>{header}<div className="grid-2"><section className="panel"><div className="panel-head"><div><h2>Registrar mídia</h2><p>Centralize caminhos e URLs sem duplicar o arquivo original.</p></div></div><form action={registerMediaAsset} className="form-stack"><div className="field"><label>Nome</label><input className="input" name="name" required/></div><div className="field"><label>Categoria</label><select className="select" name="category" defaultValue="other"><option value="mascot">Mascote</option><option value="sticker">Adesivo</option><option value="material">Material</option><option value="illustration">Ilustração</option><option value="document">Documento</option><option value="other">Outro</option></select></div><div className="field"><label>Caminho interno</label><input className="input" name="filePath" placeholder="/mascotes/arquivo.png"/></div><div className="field"><label>URL externa</label><input className="input" name="externalUrl" placeholder="https://..."/></div><div className="field"><label>Texto alternativo</label><input className="input" name="altText"/></div><button className="button button-primary" type="submit">Adicionar à biblioteca</button></form></section><section className="panel"><div className="media-library-grid">{data?.map((m:any)=><article className="media-asset-card" key={m.id}>{m.file_path?.match(/\.(png|jpe?g|webp|gif)$/i)?<div className="media-preview"><img src={m.file_path} alt={m.alt_text||m.name}/></div>:<div className="media-placeholder">{m.category==="document"?"📄":"🗂️"}</div>}<div className="flex gap-8 wrap"><Badge tone={m.active?"green":"neutral"}>{m.category}</Badge>{m.source_entity_type&&<Badge tone="blue">{m.source_entity_type}</Badge>}</div><h3>{m.name}</h3><div className="asset-path">{m.file_path||m.external_url}</div></article>)}</div>{!data?.length&&<EmptyState title="Biblioteca vazia" description="Mascotes e materiais serão indexados aqui."/>}</section></div></>;
  }
  if (section === "acessos") {
    const {data}=await supabase.from("access_events").select("id,event_type,route,occurred_at,profiles(full_name,preferred_name)").order("occurred_at",{ascending:false}).limit(150);
    return <>{header}<section className="panel"><div className="notice">O monitoramento registra somente entrada e saída do Curió. Não armazenamos senha nem conteúdo privado neste log.</div>{data?.length?<div className="access-list">{data.map((a:any)=><article className="access-row" key={a.id}><span className={`access-dot access-${a.event_type}`}></span><div><strong>{a.profiles?.preferred_name||a.profiles?.full_name||"Usuário"}</strong><p>{a.event_type==="login"?"Entrou no Curió":"Saiu do Curió"} • {dt(a.occurred_at)}</p></div><Badge tone={a.event_type==="login"?"green":"neutral"}>{a.event_type}</Badge></article>)}</div>:<EmptyState title="Sem histórico de acesso" description="Os próximos logins e logouts serão registrados aqui."/>}</section></>;
  }
  if (section === "suporte") {
    const {data}=await supabase.from("support_tickets").select("id,subject,description,category,priority,status,created_at,updated_at,profiles!support_tickets_opened_by_user_id_fkey(full_name,preferred_name)").order("updated_at",{ascending:false}).limit(100);
    return <>{header}<section className="panel">{data?.length?<div className="form-stack">{data.map((t:any)=><article className="ticket-card" key={t.id}><div className="flex space-between gap-8 wrap"><div><strong>{t.subject}</strong><p>{t.profiles?.preferred_name||t.profiles?.full_name||"Usuário"} • {t.category}</p></div><div className="flex gap-8 wrap"><Badge tone={t.priority==="urgent"?"pink":t.priority==="high"?"yellow":"blue"}>{t.priority}</Badge><Badge tone={t.status==="closed"||t.status==="resolved"?"green":"yellow"}>{t.status}</Badge></div></div><p>{t.description}</p><form action={updateSupportTicketStatus} className="ticket-actions"><input type="hidden" name="ticketId" value={t.id}/><select className="select" name="status" defaultValue={t.status}><option value="open">Aberto</option><option value="in_progress">Em atendimento</option><option value="waiting">Aguardando</option><option value="resolved">Resolvido</option><option value="closed">Fechado</option></select><button className="button button-secondary button-small" type="submit">Atualizar</button></form></article>)}</div>:<EmptyState title="Nenhum ticket aberto" description="Solicitações dos usuários aparecerão aqui."/>}</section></>;
  }
  if (section === "turmas") {
    const {data}=await supabase.from("classes").select("id,name,school_name,academic_year,active,grades(name),class_students(student_id,active),class_teachers(teacher_id,active)").order("academic_year",{ascending:false}).order("name").limit(100);
    return <>{header}<section className="panel">{data?.length?<div className="grid-3">{data.map((c:any)=><article className="class-admin-card" key={c.id}><div className="flex space-between gap-8 wrap"><Badge tone={c.active?"green":"neutral"}>{c.active?"Ativa":"Inativa"}</Badge><span className="class-year">{c.academic_year}</span></div><h3>{c.name}</h3><p>{c.grades?.name||"Série não informada"} • {c.school_name||"Escola não informada"}</p><div className="class-metrics"><span><strong>{(c.class_students||[]).filter((x:any)=>x.active).length}</strong> alunos</span><span><strong>{(c.class_teachers||[]).filter((x:any)=>x.active).length}</strong> prof.</span></div></article>)}</div>:<EmptyState title="Nenhuma turma cadastrada" description="As turmas criadas pela equipe aparecerão aqui."/>}</section></>;
  }
  if (section === "notas") {
    const {data}=await supabase.from("grading_schemes").select("id,name,scale_min,scale_max,passing_score,active,created_at,grading_bands(id,label,min_score,max_score,color_key,sort_order)").order("created_at");
    return <>{header}<div className="notice">Notas acadêmicas ficam separadas de domínio, autonomia e confiança. Alterar uma escala não reescreve o mapa pedagógico.</div><div className="grid-2"><section className="panel"><div className="panel-head"><div><h2>Nova escala</h2><p>Defina o intervalo e a nota de referência.</p></div></div><form action={createGradingScheme} className="form-stack"><div className="field"><label>Nome</label><input className="input" name="name" placeholder="Ex.: Escala 0–100" required/></div><div className="form-row"><div className="field"><label>Mínimo</label><input className="input" name="min" type="number" step="0.1" defaultValue="0" required/></div><div className="field"><label>Máximo</label><input className="input" name="max" type="number" step="0.1" defaultValue="10" required/></div></div><div className="field"><label>Nota de referência</label><input className="input" name="passing" type="number" step="0.1" defaultValue="6"/></div><button className="button button-primary" type="submit">Criar escala</button></form></section><section className="panel">{data?.length?<div className="form-stack">{data.map((s:any)=><article className="grading-card" key={s.id}><div className="flex space-between gap-8 wrap"><div><h3>{s.name}</h3><p>{s.scale_min} a {s.scale_max} • referência {s.passing_score??"—"}</p></div><Badge tone={s.active?"green":"neutral"}>{s.active?"Ativa":"Inativa"}</Badge></div>{s.grading_bands?.length?<div className="grading-bands">{[...s.grading_bands].sort((a:any,b:any)=>a.sort_order-b.sort_order).map((b:any)=><span className={`grading-band band-${b.color_key}`} key={b.id}><strong>{b.label}</strong><small>{b.min_score}–{b.max_score}</small></span>)}</div>:<small className="muted">Sem faixas configuradas.</small>}<form action={addGradingBand} className="grading-band-form"><input type="hidden" name="schemeId" value={s.id}/><input className="input" name="label" placeholder="Nome da faixa" required/><input className="input" name="min" type="number" step="0.1" placeholder="Mín." required/><input className="input" name="max" type="number" step="0.1" placeholder="Máx." required/><select className="select" name="color" defaultValue="blue"><option value="pink">Rosa</option><option value="yellow">Amarelo</option><option value="blue">Azul</option><option value="green">Verde</option><option value="neutral">Neutro</option></select><button className="button button-secondary button-small" type="submit">Adicionar faixa</button></form></article>)}</div>:<EmptyState title="Nenhuma escala" description="Crie a primeira configuração de notas."/>}</section></div></>;
  }

  if (section === "lixeira") {
    const {data}=await supabase.from("trash_items").select("id,entity_type,entity_id,entity_snapshot,deleted_at,restore_until,restored_at").is("restored_at",null).order("deleted_at",{ascending:false}).limit(80);
    return <>{header}{feedback}<section className="panel">{data?.length?<div className="form-stack">{data.map((i:any)=><article className="mission-card" key={i.id}><div className="flex space-between gap-8 wrap"><div><strong>{i.entity_snapshot?.label || i.entity_type}</strong><p>{i.entity_type}</p></div><Badge tone="neutral">Na lixeira</Badge></div><small className="muted">Removido em {dt(i.deleted_at)} • restaurável até {dt(i.restore_until)}</small>{i.entity_type === "plans" && <form action={restoreTrashItem} className="mt-12"><input type="hidden" name="trashId" value={i.id}/><button className="button button-secondary button-small" type="submit">Restaurar como rascunho</button></form>}</article>)}</div>:<EmptyState title="Lixeira vazia" description="Itens removidos aparecerão aqui durante a janela de restauração."/>}</section></>;
  }
  if (section === "configuracoes") {
    const {data}=await supabase.from("app_settings").select("key,value,is_public,updated_at").order("key");
    return <>{header}<section className="panel"><div className="notice">Configurações sensíveis permanecem restritas ao Admin. Valores públicos podem abastecer o site sem expor segredos.</div>{data?.length?<div className="form-stack">{data.map((s:any)=><article className="mission-card" key={s.key}><div className="flex space-between gap-8 wrap"><strong>{s.key}</strong><Badge tone={s.is_public?"green":"neutral"}>{s.is_public?"Público":"Interno"}</Badge></div><small className="muted">Atualizado em {dt(s.updated_at)}</small></article>)}</div>:<EmptyState title="Nenhuma configuração registrada" description="Parâmetros da aplicação aparecerão aqui."/>}</section></>;
  }
  notFound();
}
